'use strict';
/*
 * Test harness: a mock Streamable-HTTP MCP server plus a driver that runs the
 * REAL connector binary as a subprocess and speaks stdio JSON-RPC to it.
 *
 * Everything is exercised end to end through the same path an MCP client uses —
 * spawn, write newline-delimited JSON to stdin, read it back from stdout. No
 * module internals are reached into, because the wire behaviour IS the contract.
 */

const http = require('http');
const path = require('path');
const { spawn } = require('child_process');

const BIN = path.join(__dirname, '..', 'index.js');

/**
 * Start a mock server. `handler(msg, req)` returns:
 *   { status?, headers?, body? }   — body may be a string or a JSON value
 * or undefined for a default 200 JSON-RPC "method not found".
 * Resolves to { port, url, requests, close }.
 */
function startServer(handler) {
  const requests = [];
  const server = http.createServer((req, res) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      let msg = null;
      try { msg = JSON.parse(raw); } catch (_) { /* leave null */ }
      requests.push({ method: req.method, url: req.url, headers: req.headers, raw, msg });

      const reply = (out) => {
        if (!out) {
          out = { status: 200, body: { jsonrpc: '2.0', id: msg && msg.id, error: { code: -32601, message: 'no handler' } } };
        }
        const status = out.status || 200;
        const headers = Object.assign(
          { 'Content-Type': out.contentType || 'application/json' },
          out.headers || {}
        );
        if (out.body === undefined || out.body === null) {
          res.writeHead(status, headers);
          return res.end();
        }
        const body = typeof out.body === 'string' ? out.body : JSON.stringify(out.body);
        res.writeHead(status, headers);
        res.end(body);
      };

      // Handlers may be async — the drain test needs a genuinely slow reply.
      Promise.resolve()
        .then(() => handler(msg, req, requests.length))
        .then(reply)
        .catch((err) => { res.writeHead(500); res.end(String(err && err.message)); });
    });
  });

  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const port = server.address().port;
      resolve({
        port,
        url: 'http://127.0.0.1:' + port,
        requests,
        close: () => new Promise((r) => server.close(r)),
      });
    });
  });
}

/**
 * Run the connector.
 *   opts.args      extra argv (array)
 *   opts.env       extra env vars
 *   opts.send      array of values written to stdin as JSON lines (strings are
 *                  written verbatim, so malformed input can be tested)
 *   opts.expect    resolve as soon as this many stdout lines have arrived
 *   opts.timeoutMs overall cap (default 20000, or $WRIT_TEST_TIMEOUT_MS)
 * Resolves to { out, err, lines, code }.
 *
 * TIMING. Every case here spawns a real `node` process and, usually, an HTTP
 * server beside it. The cap used to be 5s and a timeout resolved SILENTLY with
 * whatever had arrived — so on a loaded machine a test failed as
 * `Cannot read properties of undefined (reading 'id')` on line 0 of an empty
 * array, which says nothing about the cause. Six different cases failed that way
 * on one run and none on the next, and the publish script runs this suite as a
 * release guard, so the flake blocked publishing at random.
 *
 * Now: the cap is generous (a real hang is still caught, just later), and a
 * timeout that did not produce the expected output REJECTS with what was
 * actually seen, including the connector's stderr.
 */
function runConnector(opts) {
  const o = opts || {};
  const timeoutMs = o.timeoutMs || Number(process.env.WRIT_TEST_TIMEOUT_MS || 20000);
  const expect = o.expect === undefined ? 0 : o.expect;

  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [BIN].concat(o.args || []), {
      env: Object.assign({}, process.env, { WRIT_API_KEY: '' }, o.env || {}),
      stdio: ['pipe', 'pipe', 'pipe'],
    });

    let out = '';
    let err = '';
    let settled = false;
    let timedOut = false;
    const lines = () => out.split('\n').filter(Boolean).map((l) => JSON.parse(l));

    const finish = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try { child.stdin.end(); } catch (_) { /* already closed */ }
      // Give the process a moment to exit cleanly, then report.
      const done = () => {
        const got = out.split('\n').filter(Boolean).length;
        if (timedOut && expect > 0 && got < expect) {
          return reject(new Error(
            'the connector produced ' + got + ' of ' + expect + ' expected stdout line(s) ' +
            'within ' + timeoutMs + 'ms.\n--- stdout ---\n' + out + '\n--- stderr ---\n' + err));
        }
        resolve({ out, err, lines: lines(), code: child.exitCode });
      };
      if (child.exitCode !== null) return done();
      child.once('exit', done);
      setTimeout(() => { try { child.kill(); } catch (_) {} done(); }, 400);
    };

    const timer = setTimeout(() => { timedOut = true; finish(); }, timeoutMs);

    const queue = (o.send || []).slice();
    const write = (m) => child.stdin.write(typeof m === 'string' ? m : JSON.stringify(m) + '\n');

    child.stdout.on('data', (d) => {
      out += d;
      const got = out.split('\n').filter(Boolean).length;
      // `staged` models a real MCP client, which waits for each reply before
      // sending the next request (notably: nothing goes out before initialize
      // returns, which is how session pinning can work at all).
      if (o.staged && queue.length) write(queue.shift());
      if (expect > 0 && got >= expect) {
        // Let any trailing write flush before we tear down.
        setTimeout(finish, 60);
      }
    });
    child.stderr.on('data', (d) => { err += d; });
    child.on('exit', () => { if (expect === 0) setTimeout(finish, 30); });

    if (o.staged) {
      if (queue.length) write(queue.shift());
    } else {
      while (queue.length) write(queue.shift());
    }
    if (!expect) child.stdin.end();
  });
}

const INIT = {
  jsonrpc: '2.0',
  id: 1,
  method: 'initialize',
  params: { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'test', version: '1' } },
};

const okResult = (id, result) => ({ jsonrpc: '2.0', id, result });

module.exports = { startServer, runConnector, BIN, INIT, okResult };

'use strict';
/* Config resolution, target selection, and the credential-exposure warnings. */

const { test } = require('node:test');
const assert = require('node:assert');
const { spawn } = require('node:child_process');
const path = require('node:path');
const { startServer, runConnector } = require('./helpers');

const BIN = path.join(__dirname, '..', 'index.js');
const PKG = require('../package.json');

// Run to completion and capture everything, including a non-zero exit. stdin is
// closed immediately: a healthy connector exits as soon as its input ends, which
// is also what keeps this suite fast.
function cli(args, env) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [BIN].concat(args || []), {
      env: Object.assign(
        {}, process.env,
        { WRIT_API_KEY: '', WRIT_COORDINATOR_URL: '', WRIT_URL: '', WRIT_INSECURE_TLS: '' },
        env || {}
      ),
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => { stdout += d; });
    child.stderr.on('data', (d) => { stderr += d; });
    child.stdin.end();
    const kill = setTimeout(() => child.kill(), 8000);
    child.on('exit', (code) => { clearTimeout(kill); resolve({ code, stdout, stderr }); });
  });
}

test('--version prints the package version on stdout', async () => {
  const r = await cli(['--version']);
  assert.equal(r.code, 0);
  assert.equal(r.stdout.trim(), PKG.version);
});

test('--help prints usage on stdout and exits 0', async () => {
  const r = await cli(['--help']);
  assert.equal(r.code, 0);
  assert.match(r.stdout, /Usage: writ-mcp/);
  assert.match(r.stdout, /api\.usewrit\.app/);
});

test('a missing API key fails fast with an actionable message', async () => {
  const r = await cli([]);
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /Missing API key/);
  assert.match(r.stderr, /WRIT_API_KEY/);
});

// A typo'd flag used to be swallowed and resurface as a confusing "missing key".
test('an unknown flag is named, not silently ignored', async () => {
  const r = await cli(['--api_key', 'wt_x']);
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /Unknown option/);
  assert.match(r.stderr, /--api_key/);
});

test('an invalid timeout is rejected instead of silently defaulting', async () => {
  const r = await cli(['--timeout', 'soon'], { WRIT_API_KEY: 'wt_x' });
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /Invalid timeout/);
});

test('a non-http URL is rejected', async () => {
  const r = await cli(['--url', 'ftp://example.com'], { WRIT_API_KEY: 'wt_x' });
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /Invalid --url/);
});

test('with no --url the target is Writ Cloud at api.usewrit.app/mcp', async () => {
  const r = await cli([], { WRIT_API_KEY: 'wt_x' });
  assert.match(r.stderr, /target: Writ Cloud/);
  assert.match(r.stderr, /https:\/\/api\.usewrit\.app\/mcp/);
});

test('a base URL gets /mcp appended; an /mcp URL is used verbatim', async () => {
  const base = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://writ.example.com' });
  assert.match(base.stderr, /https:\/\/writ\.example\.com\/mcp\b/);

  const exact = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://writ.example.com/mcp' });
  assert.match(exact.stderr, /https:\/\/writ\.example\.com\/mcp\b/);
  assert.doesNotMatch(exact.stderr, /\/mcp\/mcp/);

  const slug = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://mcp.usewrit.app/mcp/my-tools' });
  assert.match(slug.stderr, /target: published MCP endpoint/);
  assert.match(slug.stderr, /\/mcp\/my-tools/);
});

test('a trailing slash does not produce a doubled path', async () => {
  const r = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://writ.example.com/' });
  assert.match(r.stderr, /https:\/\/writ\.example\.com\/mcp\b/);
});

test('flags beat environment variables', async () => {
  const r = await cli(['--url', 'https://from-flag.example.com'], {
    WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://from-env.example.com',
  });
  assert.match(r.stderr, /from-flag\.example\.com/);
});

// Each of these is a distinct way the Bearer key can leak. All must be loud.
test('plaintext HTTP to a non-loopback host warns about the key in the clear', async () => {
  const r = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'http://writ.example.com' });
  assert.match(r.stderr, /UNENCRYPTED/);
});

test('plaintext HTTP to localhost does NOT warn', async () => {
  const r = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'http://localhost:8000' });
  assert.doesNotMatch(r.stderr, /UNENCRYPTED/);
});

test('--insecure warns that certificate verification is off', async () => {
  const r = await cli(['--insecure'], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://writ.example.com' });
  assert.match(r.stderr, /certificate verification is DISABLED/);
});

test('--api-key warns that the key is visible in ps', async () => {
  const r = await cli(['--api-key', 'wt_x', '--url', 'https://writ.example.com']);
  assert.match(r.stderr, /`ps`/);
});

test('WRIT_API_KEY alone produces no ps warning', async () => {
  const r = await cli([], { WRIT_API_KEY: 'wt_x', WRIT_COORDINATOR_URL: 'https://writ.example.com' });
  assert.doesNotMatch(r.stderr, /`ps`/);
});

test('the package ships zero runtime dependencies', () => {
  assert.equal(PKG.dependencies, undefined, 'writ-mcp must stay dependency-free');
  assert.equal(PKG.devDependencies, undefined, 'tests use node:test only');
});

// REGRESSION: `WRIT_API_KEY=$(cat key.txt)` and pasting from the app's UI both
// bring whitespace. Untrimmed, the newline reaches Node's header writer, which
// throws ERR_INVALID_CHAR inside EVERY request — surfacing to the user as
// "Cannot reach <target> (Invalid character in header content)", i.e. blaming
// the network for a credential that is one character off.
test('a key with surrounding whitespace is trimmed, not sent verbatim', async () => {
  const srv = await startServer((msg) => ({ body: { jsonrpc: '2.0', id: msg.id, result: { ok: true } } }));
  const r = await runConnector({
    args: ['--url', srv.url], env: { WRIT_API_KEY: '  wt_padded_key\n' }, expect: 1,
    send: [{ jsonrpc: '2.0', id: 1, method: 'ping' }],
  });
  await srv.close();

  assert.equal(srv.requests[0].headers.authorization, 'Bearer wt_padded_key');
  assert.ok(r.lines[0].result, 'the request must succeed, not fail as unreachable');
});

test('a "Bearer <key>" value is accepted without doubling the scheme', async () => {
  const srv = await startServer((msg) => ({ body: { jsonrpc: '2.0', id: msg.id, result: { ok: true } } }));
  const r = await runConnector({
    args: ['--url', srv.url], env: { WRIT_API_KEY: 'Bearer wt_prefixed' }, expect: 1,
    send: [{ jsonrpc: '2.0', id: 1, method: 'ping' }],
  });
  await srv.close();
  assert.equal(srv.requests[0].headers.authorization, 'Bearer wt_prefixed');
});

test('a key with an interior control character is rejected at startup, with the cause named', async () => {
  const r = await cli([], { WRIT_API_KEY: 'wt_bad\tkey', WRIT_COORDINATOR_URL: 'https://writ.example.com' });
  assert.equal(r.code, 1);
  assert.match(r.stderr, /cannot be sent in an HTTP header/);
  assert.doesNotMatch(r.stderr, /Cannot reach/);
});

// MCP clients persist a server's stderr to a log file on disk (Claude Code
// writes mcp-logs-<name>/*.jsonl), so anything echoed here is written down.
test('credentials embedded in --url are never echoed into the client log', async () => {
  const r = await cli([], {
    WRIT_API_KEY: 'wt_x',
    WRIT_COORDINATOR_URL: 'https://someone:hunter2@writ.example.com',
  });
  assert.doesNotMatch(r.stderr, /hunter2/, 'the password must not reach stderr');
  assert.match(r.stderr, /credentials embedded in the URL are ignored/);
});

'use strict';
/* Protocol behaviour: what the connector puts on stdout for what the server says. */

const { test } = require('node:test');
const assert = require('node:assert');
const { startServer, runConnector, INIT, okResult } = require('./helpers');

const KEY = { WRIT_API_KEY: 'wt_test_key' };

test('relays initialize and tools/list, and sends a Bearer header to /mcp', async () => {
  const srv = await startServer((msg) => {
    if (msg.method === 'initialize') {
      return { body: okResult(msg.id, { protocolVersion: '2025-06-18', serverInfo: { name: 'Mock', version: '1' }, capabilities: { tools: {} } }) };
    }
    if (msg.method === 'tools/list') {
      return { body: okResult(msg.id, { tools: [{ name: 'writ_list_workflows', inputSchema: { type: 'object' } }] }) };
    }
  });

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 2,
    send: [INIT, { jsonrpc: '2.0', id: 2, method: 'tools/list', params: {} }],
  });
  await srv.close();

  assert.equal(r.lines.length, 2);
  assert.equal(r.lines[0].id, 1);
  assert.equal(r.lines[0].result.serverInfo.name, 'Mock');
  assert.equal(r.lines[1].result.tools[0].name, 'writ_list_workflows');

  assert.equal(srv.requests[0].url, '/mcp');
  assert.equal(srv.requests[0].headers.authorization, 'Bearer wt_test_key');
  assert.match(srv.requests[0].headers.accept, /application\/json/);
  assert.match(srv.requests[0].headers.accept, /text\/event-stream/);
});

// REGRESSION: an array's `.id` is undefined too. Reading that as "notification"
// dropped every batch response on the floor and hung the client on each id.
test('relays every response in a JSON-RPC batch', async () => {
  const srv = await startServer((msg) => {
    assert.ok(Array.isArray(msg), 'server should receive the batch as an array');
    return { body: msg.filter((m) => m.id !== undefined).map((m) => okResult(m.id, { echo: m.method })) };
  });

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 2,
    send: [[{ jsonrpc: '2.0', id: 6, method: 'ping' }, { jsonrpc: '2.0', id: 7, method: 'ping' }]],
  });
  await srv.close();

  assert.equal(r.lines.length, 2, 'both batch responses must reach stdout');
  assert.deepEqual(r.lines.map((l) => l.id).sort(), [6, 7]);
});

test('a batch that fails answers every id in it, so nothing hangs', async () => {
  const srv = await startServer(() => ({ status: 502, contentType: 'text/html', body: '<html>bad gateway</html>' }));

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 2,
    send: [[{ jsonrpc: '2.0', id: 10, method: 'ping' }, { jsonrpc: '2.0', id: 11, method: 'ping' }]],
  });
  await srv.close();

  assert.equal(r.lines.length, 2);
  assert.deepEqual(r.lines.map((l) => l.id).sort(), [10, 11]);
  for (const l of r.lines) assert.equal(l.error.code, -32603);
});

test('notifications are forwarded but produce no stdout', async () => {
  const srv = await startServer(() => ({ status: 202, body: null }));

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY,
    send: [{ jsonrpc: '2.0', method: 'notifications/initialized' }],
  });
  await srv.close();

  assert.equal(srv.requests.length, 1, 'the notification must still reach the server');
  assert.equal(r.lines.length, 0, 'a notification has no reply');
});

test('202 with an id outstanding is reported, not swallowed', async () => {
  const srv = await startServer(() => ({ status: 202, body: null }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 3, method: 'ping' }],
  });
  await srv.close();

  assert.equal(r.lines.length, 1);
  assert.equal(r.lines[0].id, 3);
  assert.equal(r.lines[0].error.code, -32603);
});

test('204 No Content is treated like 202 (mcp-service answers 204)', async () => {
  const srv = await startServer(() => ({ status: 204, body: null }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY,
    send: [{ jsonrpc: '2.0', method: 'notifications/cancelled' }],
  });
  await srv.close();
  assert.equal(r.lines.length, 0);
});

test('401 becomes an actionable -32001', async () => {
  const srv = await startServer(() => ({ status: 401, body: { detail: 'nope' } }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 4, method: 'tools/list' }],
  });
  await srv.close();

  assert.equal(r.lines[0].error.code, -32001);
  assert.match(r.lines[0].error.message, /Unauthorized/);
  assert.match(r.lines[0].error.message, /API keys/);
});

test('a non-JSON body becomes -32603 rather than a crash', async () => {
  const srv = await startServer(() => ({ status: 502, contentType: 'text/html', body: '<html>nginx</html>' }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 5, method: 'ping' }],
  });
  await srv.close();

  assert.equal(r.lines[0].error.code, -32603);
  assert.match(r.lines[0].error.message, /non-JSON/);
});

test('an unreachable target becomes -32002, not a hang', async () => {
  // Port 1 is reserved and refuses instantly.
  const r = await runConnector({
    args: ['--url', 'http://127.0.0.1:1'], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 9, method: 'ping' }],
  });
  assert.equal(r.lines[0].error.code, -32002);
  assert.match(r.lines[0].error.message, /Cannot reach/);
});

test('an SSE-framed response is decoded (spec allows it; we advertise it)', async () => {
  const srv = await startServer((msg) => ({
    contentType: 'text/event-stream',
    body: 'event: message\ndata: ' + JSON.stringify(okResult(msg.id, { via: 'sse' })) + '\n\n',
  }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 12, method: 'ping' }],
  });
  await srv.close();

  assert.equal(r.lines[0].id, 12);
  assert.equal(r.lines[0].result.via, 'sse');
});

test('a pinned Mcp-Session-Id and protocol version are echoed on later requests', async () => {
  const srv = await startServer((msg) => {
    if (msg.method === 'initialize') {
      return {
        headers: { 'Mcp-Session-Id': 'sess-abc123' },
        body: okResult(msg.id, { protocolVersion: '2025-06-18', serverInfo: { name: 'Mock', version: '1' }, capabilities: {} }),
      };
    }
    return { body: okResult(msg.id, { ok: true }) };
  });

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 2, staged: true,
    send: [INIT, { jsonrpc: '2.0', id: 2, method: 'ping' }],
  });
  await srv.close();

  assert.equal(r.lines.length, 2);
  const second = srv.requests[1];
  assert.equal(second.headers['mcp-session-id'], 'sess-abc123');
  assert.equal(second.headers['mcp-protocol-version'], '2025-06-18');
  assert.equal(srv.requests[0].headers['mcp-session-id'], undefined, 'no session on the first call');
});

test('tools/call is never retried — a workflow must not run twice', async () => {
  let calls = 0;
  const srv = await startServer((msg) => {
    calls++;
    return { status: 503, body: { error: 'busy' } };
  });

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 20, method: 'tools/call', params: { name: 'run_x', arguments: {} } }],
  });
  await srv.close();

  assert.equal(calls, 1, 'a side-effecting call must be sent exactly once');
  // …and the caller still gets an addressable failure rather than the server's
  // bare `{"error": "busy"}` body, which carries no id and would hang the client.
  assert.equal(r.lines.length, 1);
  assert.equal(r.lines[0].id, 20);
  assert.equal(r.lines[0].error.code, -32002);
});

test('a JSON body that is not a JSON-RPC response never reaches stdout raw', async () => {
  const srv = await startServer(() => ({ status: 429, body: { detail: 'rate limited' } }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 22, method: 'ping' }],
  });
  await srv.close();

  assert.equal(r.lines[0].id, 22, 'the reply must be addressable to the pending id');
  assert.match(r.lines[0].error.message, /not a JSON-RPC response/);
});

test('tools/list IS retried on a transient 503 and then succeeds', async () => {
  let calls = 0;
  const srv = await startServer((msg) => {
    calls++;
    if (calls < 3) return { status: 503, body: { error: 'busy' } };
    return { body: okResult(msg.id, { tools: [] }) };
  });

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1, timeoutMs: 8000,
    send: [{ jsonrpc: '2.0', id: 21, method: 'tools/list' }],
  });
  await srv.close();

  assert.equal(calls, 3, 'read-only method should have been retried');
  assert.deepEqual(r.lines[0].result.tools, []);
});

test('an unparseable stdin line is dropped without killing the session', async () => {
  const srv = await startServer((msg) => ({ body: okResult(msg.id, { ok: true }) }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: ['{{{ not json\n', { jsonrpc: '2.0', id: 30, method: 'ping' }],
  });
  await srv.close();

  assert.match(r.err, /unparseable/);
  assert.equal(r.lines[0].id, 30, 'the session survives bad input');
});

test('stdout carries only JSON-RPC — diagnostics go to stderr', async () => {
  const srv = await startServer((msg) => ({ body: okResult(msg.id, { ok: true }) }));
  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 40, method: 'ping' }],
  });
  await srv.close();

  for (const line of r.out.split('\n').filter(Boolean)) {
    assert.doesNotThrow(() => JSON.parse(line), 'every stdout line must be valid JSON');
  }
  assert.match(r.err, /\[writ-mcp\] target:/);
});

// stdin EOF must not kill a request that is still in flight — a workflow run can
// legitimately take minutes, and the client is waiting on its id.
test('in-flight requests drain before exit when stdin closes', async () => {
  const srv = await startServer((msg) => new Promise((resolve) => {
    setTimeout(() => resolve({ body: okResult(msg.id, { slow: true }) }), 400);
  }));

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 50, method: 'ping' }],
  });
  await srv.close();

  assert.equal(r.lines.length, 1, 'the slow reply must still arrive');
  assert.equal(r.lines[0].result.slow, true);
});

// REGRESSION: the connector used to relay whatever the server sent and stop
// there. A response that does not address an id we sent — a gateway serving a
// cached body, a proxy that rewrites the payload, a server answering a batch
// with one object — left the client blocked on that id forever. On `initialize`
// that means the MCP server never finishes starting and the client just reports
// "failed to connect" with nothing to go on.
test('an id the server never answers is backfilled, not left hanging', async () => {
  const srv = await startServer(() => ({
    // Well-formed JSON-RPC, wrong id.
    body: { jsonrpc: '2.0', id: 999, result: { ok: true } },
  }));

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 2,
    send: [INIT],
  });
  await srv.close();

  const forOne = r.lines.find((l) => l.id === 1);
  assert.ok(forOne, 'id 1 must be answered even though the server addressed id 999');
  assert.equal(forOne.error.code, -32603);
  assert.match(forOne.error.message, /no response for request id 1/);
  // The server's own message is still relayed — a POST response may legitimately
  // carry server-initiated traffic, so we add, never filter.
  assert.ok(r.lines.some((l) => l.id === 999), 'the server payload is still relayed');
});

test('a batch where the server answers only some ids backfills the rest', async () => {
  const srv = await startServer((msg) => ({
    body: [okResult(msg[0].id, { echo: 1 })],  // second id silently dropped
  }));

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 2,
    send: [[
      { jsonrpc: '2.0', id: 11, method: 'tools/list', params: {} },
      { jsonrpc: '2.0', id: 12, method: 'ping', params: {} },
    ]],
  });
  await srv.close();

  assert.ok(r.lines.find((l) => l.id === 11 && l.result), 'id 11 answered normally');
  const missing = r.lines.find((l) => l.id === 12);
  assert.ok(missing, 'id 12 must not hang');
  assert.match(missing.error.message, /no response for request id 12/);
});

// A 301/302 is what a reverse proxy doing http -> https returns. Node does not
// follow redirects (correctly — replaying the Authorization header to a new
// origin would hand the API key to a host the user never chose), so the body is
// empty and this used to surface as the useless "Empty response from ...".
test('a redirect is named and explained rather than reported as an empty response', async () => {
  const srv = await startServer(() => ({
    status: 301,
    headers: { Location: 'https://writ.example.com/mcp' },
    body: null,
  }));

  const r = await runConnector({
    args: ['--url', srv.url], env: KEY, expect: 1,
    send: [{ jsonrpc: '2.0', id: 3, method: 'tools/list', params: {} }],
  });
  await srv.close();

  assert.equal(r.lines[0].id, 3);
  assert.match(r.lines[0].error.message, /redirected \(HTTP 301\)/);
  assert.match(r.lines[0].error.message, /https:\/\/writ\.example\.com\/mcp/);
  assert.match(r.lines[0].error.message, /would leak it/);
});

#!/usr/bin/env node
/*
 * writ-mcp — the official Writ MCP server connector.
 *
 * A thin stdio <-> HTTP bridge that works against BOTH Writ Cloud and a
 * self-hosted Writ coordinator. MCP clients that speak stdio (Claude Code,
 * Claude Desktop, Cursor, Windsurf, Codex, …) launch this process and exchange
 * newline-delimited JSON-RPC 2.0 over stdin/stdout. We forward each message
 * verbatim to the target's Streamable-HTTP MCP endpoint with an
 * Authorization: Bearer header, and relay the response back. ALL tools and
 * business logic live server-side — this connector holds none, so it can never
 * drift from the app.
 *
 * Targets (pick one). The key rides in the environment: `claude mcp add` takes
 * `-e KEY=value` before the `--`, so it is stored in the client's config file
 * instead of the process table.
 *   Writ Cloud (default — no --url needed):
 *     claude mcp add writ-cloud -e WRIT_API_KEY=wt_... -- npx -y writ-mcp
 *   Self-hosted coordinator:
 *     claude mcp add writ-selfhost -e WRIT_API_KEY=wt_... -- npx -y writ-mcp --url https://writ.example.com
 *   A published per-workflow MCP endpoint (an "Expose as MCP" slug URL) is used
 *   verbatim:
 *     claude mcp add my-tools -e WRIT_API_KEY=wt_... -- npx -y writ-mcp --url https://mcp.usewrit.app/mcp/my-tools
 *
 * Config (flags take precedence over env):
 *   --url <URL>        WRIT_COORDINATOR_URL | WRIT_URL   (default: Writ Cloud)
 *   --api-key <KEY>    WRIT_API_KEY  (prefer the env var — see below)
 *   --insecure         WRIT_INSECURE_TLS=1   (accept a self-signed local-CA cert)
 *   --timeout <ms>     WRIT_MCP_TIMEOUT_MS   (per-request; default 600000)
 *
 * Prefer WRIT_API_KEY over --api-key: a key on the command line is readable by
 * any local process through `ps` and is written to your shell history.
 *
 * Zero dependencies, built on Node's core http/https.
 * The API key is created in the Writ app: Settings -> Developers -> API keys.
 */
'use strict';

const http = require('http');
const https = require('https');
const readline = require('readline');
const { URL } = require('url');

// ── Constants ────────────────────────────────────────────────────────────────

// Writ Cloud's REST base. The account-wide MCP endpoint is POST <base>/mcp;
// published per-workflow endpoints live on their own host (mcp.usewrit.app) and
// are passed to --url verbatim.
const CLOUD_BASE = 'https://api.usewrit.app';

// Cap on a single response body. A broken or hostile server must not be able to
// grow this process until the OS kills it — the client would just see the MCP
// server vanish mid-session with no explanation.
const MAX_RESPONSE_BYTES = 32 * 1024 * 1024;

// Methods that are safe to re-send after a transient failure. Everything else —
// above all tools/call, which RUNS a workflow — is sent exactly once, because a
// retry could double-execute a side effect we cannot see.
const RETRY_SAFE_METHODS = new Set([
  'initialize', 'ping', 'tools/list', 'resources/list', 'prompts/list',
]);

// Errors that prove the request never reached the app: no connection was ever
// established. These are safe to retry for ANY method.
const NEVER_DELIVERED = new Set([
  'ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN', 'EHOSTUNREACH', 'ENETUNREACH',
]);

const RETRY_STATUS = new Set([429, 502, 503, 504]);
const MAX_ATTEMPTS = 3;

const LOOPBACK = new Set(['localhost', '127.0.0.1', '::1', '[::1]', '0.0.0.0']);

// ── Config ───────────────────────────────────────────────────────────────────

function parseArgs(argv) {
  const out = { unknown: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--url') out.url = argv[++i];
    else if (a === '--api-key' || a === '--key') { out.apiKey = argv[++i]; out.keyOnArgv = true; }
    else if (a === '--insecure' || a === '--insecure-tls') out.insecure = true;
    else if (a === '--timeout') out.timeout = argv[++i];
    else if (a === '--help' || a === '-h') out.help = true;
    else if (a === '--version' || a === '-v') out.version = true;
    else if (a.startsWith('--url=')) out.url = a.slice(6);
    else if (a.startsWith('--api-key=')) { out.apiKey = a.slice(10); out.keyOnArgv = true; }
    else if (a.startsWith('--timeout=')) out.timeout = a.slice(10);
    // A mistyped flag must not fail silently as "missing api key" — name it.
    else out.unknown.push(a);
  }
  return out;
}

const args = parseArgs(process.argv.slice(2));

const HELP =
  'writ-mcp — the official Writ MCP server connector (Writ Cloud + self-host)\n\n' +
  // --api-key is bracketed, not required: the key normally arrives as
  // WRIT_API_KEY, and exactly one of the two has to be present.
  'Usage: writ-mcp [--url <url>] [--api-key <key>] [--insecure] [--timeout <ms>]\n\n' +
  'Without --url it targets Writ Cloud (' + CLOUD_BASE + '). Pass --url for a\n' +
  'self-hosted coordinator, or a published /mcp/<slug> endpoint URL to use it\n' +
  'verbatim.\n\n' +
  'Env:  WRIT_COORDINATOR_URL | WRIT_URL, WRIT_API_KEY, WRIT_INSECURE_TLS, WRIT_MCP_TIMEOUT_MS\n' +
  'The key also accepts --api-key, but prefer WRIT_API_KEY: a key on the command\n' +
  'line is visible in `ps` and recorded in your shell history.\n\n' +
  'Add to Claude Code (-e sets the env var, and must precede the --):\n' +
  '  claude mcp add writ-cloud    -e WRIT_API_KEY=<YOUR_KEY> -- npx -y writ-mcp\n' +
  '  claude mcp add writ-selfhost -e WRIT_API_KEY=<YOUR_KEY> -- npx -y writ-mcp --url https://writ.example.com\n';

// --help / --version are explicit queries that exit immediately, so stdout is
// not yet the JSON-RPC channel and is the right place for the answer.
if (args.help) {
  process.stdout.write(HELP);
  process.exit(0);
}
if (args.version) {
  process.stdout.write((require('./package.json').version || '0.0.0') + '\n');
  process.exit(0);
}

function die(msg) {
  process.stderr.write('[writ-mcp] ' + msg + '\n');
  process.exit(1);
}

function warn(msg) {
  process.stderr.write('[writ-mcp] ' + msg + '\n');
}

if (args.unknown.length) {
  die('Unknown option(s): ' + args.unknown.join(' ') + '\n\n' + HELP);
}

const RAW_URL =
  args.url ||
  process.env.WRIT_COORDINATOR_URL ||
  process.env.WRIT_URL ||
  CLOUD_BASE;
// Trimmed, because the overwhelmingly common way to supply a key is a paste from
// the app's UI or `WRIT_API_KEY=$(cat key.txt)` — both of which bring surrounding
// whitespace, and a newline in a header value is rejected by Node deep inside the
// transport, surfacing as a per-request "Cannot reach <target>" that blames the
// network for a typo. `Bearer ` is stripped too so either form normalizes.
const API_KEY = String(args.apiKey || process.env.WRIT_API_KEY || '')
  .trim()
  .replace(/^bearer\s+/i, '')
  .trim();
const INSECURE =
  args.insecure ||
  ['1', 'true', 'yes'].includes(String(process.env.WRIT_INSECURE_TLS || '').toLowerCase());

let TIMEOUT_MS = 600000;
if (args.timeout !== undefined || process.env.WRIT_MCP_TIMEOUT_MS) {
  const raw = args.timeout !== undefined ? args.timeout : process.env.WRIT_MCP_TIMEOUT_MS;
  const n = Number(raw);
  if (!Number.isFinite(n) || n <= 0) {
    die('Invalid timeout: ' + raw + ' (expected a positive number of milliseconds).');
  }
  TIMEOUT_MS = n;
}

if (!API_KEY) {
  die(
    'Missing API key. Set WRIT_API_KEY (preferred — a key passed as --api-key is ' +
    'visible to any local process via `ps` and is recorded in your shell history). ' +
    'Create one in the Writ app under Settings -> Developers -> API keys.'
  );
}

// Reject a key that cannot legally go in an HTTP header, HERE, where we can name
// the cause. Otherwise Node throws ERR_INVALID_CHAR inside every request and the
// user sees "Cannot reach <target> (Invalid character in header content)" — a
// message that points at the network for what is really a malformed credential.
// Writ keys are `wt_` + URL-safe base64, so printable-non-space is the right set.
if (!/^[\x21-\x7e]+$/.test(API_KEY)) {
  die(
    'The API key contains characters that cannot be sent in an HTTP header ' +
    '(whitespace, a newline, or a control character). Surrounding whitespace is ' +
    'already trimmed, so this is something inside the key itself — re-copy it from ' +
    'Settings -> Developers -> API keys. A Writ key looks like wt_ followed by ' +
    'letters, digits, - and _.'
  );
}

// Build the MCP endpoint URL. A base URL gets '/mcp' appended; a URL whose path
// already IS an MCP endpoint — '/mcp' exact (any server's native endpoint) or
// '/mcp/<slug>' (a published per-workflow endpoint) — is used verbatim, so
// copy-pasted endpoint URLs work without double-appending.
let ENDPOINT;
try {
  const trimmed = RAW_URL.replace(/\/+$/, '');
  const probe = new URL(trimmed);
  if (probe.protocol !== 'http:' && probe.protocol !== 'https:') {
    die('Invalid --url: ' + RAW_URL + ' (expected an http:// or https:// URL).');
  }
  const isMcpPath = probe.pathname === '/mcp' || probe.pathname.startsWith('/mcp/');
  ENDPOINT = isMcpPath ? probe : new URL(trimmed + '/mcp');
} catch (_) {
  die('Invalid --url: ' + RAW_URL);
}
const TRANSPORT = ENDPOINT.protocol === 'https:' ? https : http;
const AGENT = new TRANSPORT.Agent({ keepAlive: true, maxSockets: 8 });
const AUTH = 'Bearer ' + API_KEY;

// The URL as it is safe to PRINT. `https://user:pass@host/…` is a legal URL, and
// every diagnostic below interpolates the endpoint — but MCP clients persist a
// server's stderr to a log file on disk (Claude Code writes `mcp-logs-<name>/*.jsonl`),
// so echoing the href verbatim would write that password to disk in plaintext.
// The request itself never carries the userinfo: opts below are built from
// hostname/port/path only, so it is dropped either way. Say so rather than
// letting it look like it was applied.
const SAFE_HREF = (() => {
  const u = new URL(ENDPOINT.href);
  if (!u.username && !u.password) return u.href;
  u.username = '';
  u.password = '';
  return u.href;
})();
if (ENDPOINT.username || ENDPOINT.password) {
  warn(
    'NOTE: credentials embedded in the URL are ignored — Writ authenticates with ' +
    'the API key in the Authorization header. Remove them from --url; they are not ' +
    'sent, and a password in a URL tends to end up in logs and shell history.'
  );
}

// Which kind of target we resolved — used in messages so errors point users at
// the right place for keys/URLs.
const TARGET =
  ENDPOINT.hostname === new URL(CLOUD_BASE).hostname
    ? 'Writ Cloud'
    : ENDPOINT.pathname.startsWith('/mcp/')
      ? 'published MCP endpoint'
      : 'self-hosted coordinator';

// ── Credential-exposure warnings ─────────────────────────────────────────────
// Every one of these is a way the Bearer key leaks. Say so loudly at startup —
// stderr is surfaced in MCP client logs.

// SECURITY (audit #40): insecure TLS disables certificate verification, exposing
// the Bearer API key to a man-in-the-middle. Only for a trusted local self-signed
// CA on a private network — never against a remote/public coordinator.
if (INSECURE) {
  warn(
    'WARNING: TLS certificate verification is DISABLED (--insecure / WRIT_INSECURE_TLS). ' +
    'Your API key can be intercepted by a man-in-the-middle. Use only on a trusted ' +
    'private network with a self-signed local CA.'
  );
}

// Plaintext HTTP to anything but loopback ships the key in the clear. This is
// the quiet sibling of --insecure and deserves the same shout.
if (ENDPOINT.protocol === 'http:' && !LOOPBACK.has(ENDPOINT.hostname)) {
  warn(
    'WARNING: ' + ENDPOINT.origin + ' is plaintext HTTP. Your API key is sent ' +
    'UNENCRYPTED over the network and is readable by anything on the path. Use ' +
    'https:// for any non-loopback target.'
  );
}

if (args.keyOnArgv) {
  warn(
    'NOTE: --api-key puts your key in this process\'s command line, where any local ' +
    'process can read it via `ps`. Prefer the WRIT_API_KEY environment variable.'
  );
}

warn(
  'target: ' + TARGET + ' — proxying stdio -> ' + SAFE_HREF +
  (INSECURE ? ' (insecure TLS)' : '')
);

// ── Session state negotiated with the server ─────────────────────────────────
// Streamable HTTP lets a server pin a session (Mcp-Session-Id) at initialize and
// require it on every later request, and the 2025-06-18 spec has clients echo the
// negotiated MCP-Protocol-Version. Writ's own endpoints are stateless and ignore
// both, but honouring them keeps this connector correct against any compliant
// MCP server — including future Writ surfaces.
let SESSION_ID = null;
let PROTOCOL_VERSION = null;

// ── HTTP request (core http/https, no deps) ──────────────────────────────────

function httpPost(bodyStr) {
  return new Promise((resolve, reject) => {
    const body = Buffer.from(bodyStr, 'utf8');
    const headers = {
      'Content-Type': 'application/json',
      // The Streamable HTTP spec requires clients to accept both; we parse
      // either shape (see extractJsonRpc).
      Accept: 'application/json, text/event-stream',
      Authorization: AUTH,
      'Content-Length': body.length,
    };
    if (SESSION_ID) headers['Mcp-Session-Id'] = SESSION_ID;
    if (PROTOCOL_VERSION) headers['MCP-Protocol-Version'] = PROTOCOL_VERSION;

    const opts = {
      method: 'POST',
      protocol: ENDPOINT.protocol,
      hostname: ENDPOINT.hostname,
      port: ENDPOINT.port || (ENDPOINT.protocol === 'https:' ? 443 : 80),
      path: ENDPOINT.pathname + ENDPOINT.search,
      headers: headers,
      agent: AGENT,
      timeout: TIMEOUT_MS,
    };
    if (ENDPOINT.protocol === 'https:' && INSECURE) opts.rejectUnauthorized = false;

    const req = TRANSPORT.request(opts, (res) => {
      const chunks = [];
      let bytes = 0;
      let aborted = false;
      res.on('data', (c) => {
        if (aborted) return;
        bytes += c.length;
        if (bytes > MAX_RESPONSE_BYTES) {
          aborted = true;
          const e = new Error('response exceeded ' + MAX_RESPONSE_BYTES + ' bytes');
          e.tooLarge = true;
          res.destroy();
          req.destroy();
          reject(e);
          return;
        }
        chunks.push(c);
      });
      res.on('end', () => {
        if (aborted) return;
        resolve({
          status: res.statusCode,
          headers: res.headers,
          text: Buffer.concat(chunks).toString('utf8'),
        });
      });
      res.on('error', (e) => { if (!aborted) reject(e); });
    });
    req.on('error', reject);
    req.on('timeout', () => {
      const e = new Error('timeout');
      e.timedOut = true;
      req.destroy(e);
    });
    req.write(body);
    req.end();
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Re-send a request only when doing so cannot double-apply a side effect:
// either the method is read-only, or the connection was never established.
function mayRetry(msg, err, status) {
  if (err && err.timedOut) return false;  // may be running server-side — never resend
  if (err && err.tooLarge) return false;
  if (err && NEVER_DELIVERED.has(err.code)) return true;
  const method = !Array.isArray(msg) && msg ? msg.method : null;
  if (!method || !RETRY_SAFE_METHODS.has(method)) return false;
  if (err) return true;                    // transport-level failure on a safe method
  return RETRY_STATUS.has(status);
}

async function postWithRetry(msg, bodyStr) {
  let lastErr = null;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const resp = await httpPost(bodyStr);
      if (attempt < MAX_ATTEMPTS && mayRetry(msg, null, resp.status)) {
        await sleep(200 * Math.pow(3, attempt - 1));
        continue;
      }
      return resp;
    } catch (err) {
      lastErr = err;
      if (attempt < MAX_ATTEMPTS && mayRetry(msg, err, null)) {
        await sleep(200 * Math.pow(3, attempt - 1));
        continue;
      }
      throw err;
    }
  }
  throw lastErr;
}

// ── Response decoding ────────────────────────────────────────────────────────

// A Streamable-HTTP server may answer a POST with either a JSON body or an SSE
// stream carrying the same JSON-RPC payload in `data:` frames. Writ answers JSON,
// but we advertise both in Accept, so we must read both.
function extractJsonRpc(contentType, text) {
  if (String(contentType || '').indexOf('text/event-stream') !== -1) {
    const payloads = [];
    for (const line of text.split('\n')) {
      const t = line.trim();
      if (t.slice(0, 5) === 'data:') {
        const d = t.slice(5).trim();
        if (d && d !== '[DONE]') payloads.push(d);
      }
    }
    if (!payloads.length) return undefined;
    // Concatenated frames: relay each as its own message.
    return payloads.map((p) => JSON.parse(p));
  }
  return JSON.parse(text);
}

// ── stdout is the JSON-RPC channel — one message per line ────────────────────

let writing = Promise.resolve();
function send(obj) {
  // Serialize writes so concurrent responses never interleave on the wire.
  writing = writing.then(() =>
    new Promise((resolve) => {
      process.stdout.write(JSON.stringify(obj) + '\n', () => resolve());
    })
  );
  return writing;
}

function rpcError(id, code, message) {
  return { jsonrpc: '2.0', id: id === undefined ? null : id, error: { code, message } };
}

// Is this actually a JSON-RPC response, or just *some* JSON?
//
// An error page from a proxy, or a framework's own `{"detail": "..."}` /
// `{"error": "busy"}` body on a 4xx/5xx, parses perfectly well as JSON. Relaying
// it verbatim puts a line on stdout that carries no id, so the client never
// learns its request failed and waits forever. Anything that is not addressable
// back to a pending id has to become a real JSON-RPC error instead.
function looksLikeJsonRpc(v) {
  if (Array.isArray(v)) return v.length > 0 && v.every(looksLikeJsonRpc);
  if (!v || typeof v !== 'object') return false;
  if (v.jsonrpc === '2.0') return true;
  return 'id' in v && ('result' in v || 'error' in v);
}

// Relay one decoded payload — a single response, or an array (SSE frames, or a
// JSON-RPC batch response) that must be emitted as separate stdio lines.
async function relay(decoded) {
  if (Array.isArray(decoded)) {
    for (const item of decoded) await send(item);
  } else if (decoded !== undefined) {
    await send(decoded);
  }
}

// Capture anything the server pinned on the way past. Only `initialize` can open
// a session, and only its result carries the negotiated protocol version.
function captureSession(msg, resp, decoded) {
  if (Array.isArray(msg) || !msg || msg.method !== 'initialize') return;
  const sid = resp.headers && resp.headers['mcp-session-id'];
  if (sid) SESSION_ID = sid;
  const one = Array.isArray(decoded) ? decoded[0] : decoded;
  const v = one && one.result && one.result.protocolVersion;
  if (v) PROTOCOL_VERSION = v;
}

// ── Forward one JSON-RPC message to the coordinator ──────────────────────────

// Every id the client is now blocked on, waiting for us to answer.
//
// A JSON-RPC BATCH is an array — and an array's `.id` is undefined, so treating
// `msg.id === undefined` as "notification" silently swallows a whole batch and
// hangs the client on every id inside it. Enumerating the ids instead means each
// failure path can unblock ALL of them, batch or not.
function expectedIds(msg) {
  if (Array.isArray(msg)) {
    return msg
      .filter((m) => m && typeof m === 'object' && m.id !== undefined)
      .map((m) => m.id);
  }
  if (msg && typeof msg === 'object' && msg.id !== undefined) return [msg.id];
  return [];  // notification, or something we can't address a reply to
}

// Every id the server actually ANSWERED in this response.
//
// A response may legitimately carry more than the answers we asked for — the
// Streamable HTTP spec lets a server put its own requests and notifications in
// the body of a POST response — so we relay everything and only use this to find
// what is MISSING. An id we sent that comes back unaddressed (a gateway serving a
// cached body, a server that answers a batch with one object, a proxy that
// rewrites the payload) leaves the client blocked on it forever, which is exactly
// the failure the batch handling above exists to prevent.
function answeredIds(decoded) {
  const list = Array.isArray(decoded) ? decoded : [decoded];
  const out = new Set();
  for (const m of list) {
    if (m && typeof m === 'object' && m.id !== undefined && ('result' in m || 'error' in m)) {
      out.add(m.id);
    }
  }
  return out;
}

async function forward(msg) {
  const ids = expectedIds(msg);

  // Answer every blocked id with the same failure, so nothing is left waiting.
  const failAll = async (code, message) => {
    for (const id of ids) await send(rpcError(id, code, message));
  };

  try {
    const resp = await postWithRetry(msg, JSON.stringify(msg));

    // 202 Accepted / 204 No Content — the server took it and has nothing to say.
    // (Writ's backend answers 202, mcp-service answers 204; both are valid for a
    // notification.) With ids outstanding it is a server bug: report, don't hang.
    if (resp.status === 202 || resp.status === 204) {
      await failAll(-32603,
        TARGET + ' accepted the request (HTTP ' + resp.status + ') but returned no response.');
      return;
    }
    if (!ids.length) return;  // notification — whatever came back, nobody is waiting

    if (resp.status === 401 || resp.status === 403) {
      await failAll(-32001,
        'Unauthorized: ' + TARGET + ' rejected the API key. Check WRIT_API_KEY / --api-key' +
        (TARGET === 'Writ Cloud'
          ? ' (create one at usewrit.app: Settings -> Developers -> API keys).'
          : ' (create one in your instance: Settings -> Developers -> API keys).'));
      return;
    }

    // A redirect is NOT followed, deliberately: replaying the Authorization
    // header to whatever origin the Location names would hand the API key to a
    // host the user never chose. Node doesn't follow them either, so without
    // this the user gets "Empty response" — a 301 from a reverse proxy doing
    // http -> https is a routine setup, and that message explains none of it.
    if (resp.status >= 300 && resp.status < 400) {
      const loc = resp.headers && resp.headers.location;
      await failAll(-32002,
        TARGET + ' redirected (HTTP ' + resp.status + ')' + (loc ? ' to ' + loc : '') +
        '. Redirects are not followed, because resending your API key to another ' +
        'origin would leak it. Point --url at the final URL instead.');
      return;
    }

    if (!resp.text) {
      await failAll(-32603, 'Empty response from ' + TARGET + '.');
      return;
    }

    let decoded;
    try {
      decoded = extractJsonRpc(resp.headers && resp.headers['content-type'], resp.text);
    } catch (_) {
      await failAll(-32603,
        TARGET + ' returned a non-JSON response (HTTP ' + resp.status + ').');
      return;
    }
    if (decoded === undefined) {
      await failAll(-32603, 'Empty response from ' + TARGET + '.');
      return;
    }
    if (!looksLikeJsonRpc(decoded)) {
      await failAll(resp.status >= 400 ? -32002 : -32603,
        TARGET + ' returned HTTP ' + resp.status + ' with a body that is not a ' +
        'JSON-RPC response.');
      return;
    }

    captureSession(msg, resp, decoded);
    await relay(decoded);

    // Backfill anything the server left unaddressed. Relaying first keeps us
    // spec-compliant (server-initiated messages pass through untouched); this
    // only guarantees the client is never left waiting on an id we sent.
    const answered = answeredIds(decoded);
    for (const id of ids) {
      if (!answered.has(id)) {
        await send(rpcError(id, -32603,
          TARGET + ' returned HTTP ' + resp.status + ' but no response for request id ' +
          JSON.stringify(id) + '.'));
      }
    }
  } catch (err) {
    if (err && err.timedOut) {
      await failAll(-32002, 'Request to ' + TARGET + ' timed out after ' + TIMEOUT_MS + 'ms.');
    } else if (err && err.tooLarge) {
      await failAll(-32002, TARGET + ' returned a response larger than ' +
        Math.round(MAX_RESPONSE_BYTES / 1024 / 1024) + 'MB — refused.');
    } else {
      await failAll(-32002, 'Cannot reach ' + TARGET + ' at ' + SAFE_HREF +
        ' (' + (err && err.message) + ').');
    }
  }
}

// ── Pump stdin lines ─────────────────────────────────────────────────────────

const rl = readline.createInterface({ input: process.stdin, terminal: false });

// Track in-flight forwards so an stdin EOF doesn't kill pending HTTP calls mid-
// request. Only exit once stdin has closed AND every forward has drained.
let pending = 0;
let closing = false;
function maybeExit() {
  if (closing && pending === 0) process.exit(0);
}

rl.on('line', (line) => {
  const s = line.trim();
  if (!s) return;
  let msg;
  try {
    msg = JSON.parse(s);
  } catch (_) {
    // Unparseable input — can't recover an id, so drop it (per JSON-RPC, a parse
    // error with no id has no addressable response).
    warn('dropped unparseable stdin line');
    return;
  }
  // Fire-and-forget: responses correlate by id, so overlap is safe.
  pending++;
  forward(msg).finally(() => {
    pending--;
    maybeExit();
  });
});

rl.on('close', () => { closing = true; maybeExit(); });
process.stdin.on('error', () => { closing = true; maybeExit(); });
process.on('SIGINT', () => process.exit(0));
process.on('SIGTERM', () => process.exit(0));
